head.script:
scwin.onpageload = function() {
    scwin.addJSON();
};
scwin.addJSON = function() {
    var jsonData = [{
        "col1": "col1",
        "col2": "col2",
        "col3": "col3",
        "col4": "col4",
        "col5": "col5"
    }, {
        "col1": "col1",
        "col2": "col2",
        "col3": "col3",
        "col4": "col4",
        "col5": "col5"
    }, {
        "col1": "col1",
        "col2": "col2",
        "col3": "col3",
        "col4": "col4",
        "col5": "col5"
    }, {
        "col1": "col1",
        "col2": "col2",
        "col3": "col3",
        "col4": "col4",
        "col5": "col5"
    }, {
        "col1": "col1",
        "col2": "col2",
        "col3": "col3",
        "col4": "col4",
        "col5": "col5"
    }, {
        "col1": "col1",
        "col2": "col2",
        "col3": "col3",
        "col4": "col4",
        "col5": "col5"
    }, {
        "col1": "col1",
        "col2": "col2",
        "col3": "col3",
        "col4": "col4",
        "col5": "col5"
    }];
    dataList1.setJSON(jsonData, true);
}
scwin.onpageunload = function() {};
scwin.trigger1_onclick = function(e) {
    scwin.addJSON();
};
scwin.trigger2_onclick = function(e) {
    dataList1.removeRow(0);
};
scwin.trigger3_onclick = function(e) {
    dataList1.removeRows([0, 1]);
};
scwin.trigger4_onclick = function(e) {
    dataList1.removeRange(0, 2);
};
scwin.trigger5_onclick = function(e) {
    dataList1.removeAll();
};
scwin.setVal = function() {
    localStorage.setItem("log", WebSquare.wUnit.getJq('#wq_uuid_8_dataLayer').height());
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.setVal()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger5').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "localStorage.getItem('log') != WebSquare.wUnit.getJq('#wq_uuid_8_dataLayer').height()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    localStorage.removeItem("log");
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
